<?php
declare(strict_types=1);
require_once __DIR__.'/fixtures/ShopAccessFixture.php';
require_once __DIR__.'/fixtures/PhotoWorkflowFixtureIsolation.php';
require_once __DIR__.'/fixtures/ImagePanelFixture.php';
use DigiForge\AI\{ImageGenerationExecution,ImageGenerationJournal,ImageGenerationPolicyRepository};
use DigiForge\Portal\{ImageGenerationPanel,CommercialResearchPanel};
final class ImageGenerationPanelTest extends WP_UnitTestCase
{
 use PhotoWorkflowFixtureIsolation {tearDown as private restoreImagePanelFixture;}
 private array $extraFloors=[];
 private array $spec;
 private array $policy;
 protected function setUp():void {parent::setUp();$_FILES=[];DigiForge\Core\Activator::activate();ShopAccessFixture::reset();$this->capturePhotoFixtureState();global $wpdb;foreach(['ai_models','ai_tasks','integrations','integration_secrets']as $method){$t=DigiForge\Database\Tables::{$method}();$this->extraFloors[$t]=(int)$wpdb->get_var('SELECT COALESCE(MAX(id),0) FROM '.$t);}wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));ShopAccessFixture::authorizeActor(get_current_user_id(),['personalized_pod'],['manage_digiforge_ai','manage_digiforge_pod','manage_digiforge_research']);DigiForge\Core\Settings::protectProduction();$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');$this->spec=ImagePanelFixture::specification();$this->policy=ImagePanelFixture::policy();}
 protected function tearDown():void {$_FILES=[];global $wpdb;foreach(array_reverse($this->extraFloors,true)as $t=>$floor)$wpdb->query('DELETE FROM '.$t.' WHERE id>'.(int)$floor);$this->restoreImagePanelFixture();}
 private function panel():ImageGenerationPanel {self::assertTrue(class_exists(ImageGenerationPanel::class),'Typed image generation portal required');return new ImageGenerationPanel();}
 private function post(string $operation,array $extra=[]):array {return ['operation'=>'design_image_'.$operation,'shop_key'=>'personalized_pod','workflow_hash'=>$this->spec['record']['commercial_hash'],'factory_hash'=>$this->spec['hash']]+$extra;}
 private function prepare():array {$out=$this->panel()->process($this->post('prepare',['policy_hash'=>$this->policy['hash'],'run_id'=>'panel-'.wp_generate_uuid4(),'started_at'=>gmdate('Y-m-d H:i:s'),'confirm'=>'1']));self::assertIsArray($out);return $out['image_job'];}
 private function html():string {ob_start();$this->panel()->render('personalized_pod',$this->spec['record']['commercial_hash'],$this->spec['hash']);return ob_get_clean();}
 public function testTypedFormsDefaultToHeldNetworkWithNoSimulatorOrRawInput():void {$html=$this->html();self::assertStringContainsString('name="policy_hash"',$html);self::assertStringContainsString('name="run_id"',$html);self::assertStringContainsString('name="_wpnonce"',$html);self::assertStringContainsString('value="digiforge_commercial_research"',$html);self::assertStringContainsString('Network execution is held',$html);self::assertStringNotContainsString('OFFLINE_SIMULATOR',$html);self::assertStringNotContainsString('name="policy_json"',$html);self::assertStringContainsString('name="task_id"',$html);self::assertStringContainsString('name="model_id"',$html);self::assertStringContainsString('name="integration_id"',$html);}
 public function testPrepareInspectAndCancelPersistNetworkIdentityWithoutDispatch():void {$job=$this->prepare();self::assertSame('NETWORK',$job['identity']['mode']);self::assertSame('PREPARED',$job['state']);self::assertSame($this->spec['hash'],$job['identity']['source_key']);$inspected=(new CommercialResearchPanel())->process($this->post('inspect',['image_job_id'=>$job['id']]));self::assertIsArray($inspected);self::assertSame($job['id'],$inspected['image_job']['id']);self::assertStringContainsString('name="quote_file"',$this->html());$cancelled=$this->panel()->process($this->post('cancel',['image_job_id'=>$job['id'],'confirm'=>'1']));self::assertIsArray($cancelled);self::assertSame('CANCELLED',$cancelled['image_job']['state']);}
 public function testRunCannotDispatchUnderStopOrWithoutExplicitConfirmation():void {$job=$this->prepare();$calls=0;$deny=static function()use(&$calls){++$calls;return new WP_Error('test_http_denied');};add_filter('pre_http_request',$deny);try {self::assertWPError($this->panel()->process($this->post('run',['image_job_id'=>$job['id'],'confirm'=>'1'])));self::assertWPError($this->panel()->process($this->post('cancel',['image_job_id'=>$job['id']])));self::assertSame(0,$calls);self::assertSame('PREPARED',(new ImageGenerationExecution())->read('personalized_pod',$job['id'])['state']);self::assertStringContainsString('disabled',$this->html());}finally{remove_filter('pre_http_request',$deny);}}
 public function testWrongCommercialSourceJobAndActorFailClosed():void {$job=$this->prepare();$p=$this->post('inspect',['image_job_id'=>$job['id']]);$p['workflow_hash']=str_repeat('f',64);self::assertWPError($this->panel()->process($p));$other=ImagePanelFixture::specification();$p=$this->post('inspect',['image_job_id'=>$job['id']]);$p['factory_hash']=$other['hash'];$p['workflow_hash']=$other['record']['commercial_hash'];self::assertWPError($this->panel()->process($p));$p['shop_key']='digital';self::assertWPError($this->panel()->process($p));wp_set_current_user(0);self::assertWPError($this->panel()->process($this->post('inspect',['image_job_id'=>$job['id']])));}
 public function testQuoteAndDerivativeRequireRealUploadedFilesAndConfirmation():void {$job=$this->prepare();foreach(['quote','derivative']as $operation){$_FILES[$operation==='quote'?'quote_file':'derivative_svg']=['name'=>$operation==='quote'?'quote.json':'art.svg','tmp_name'=>__FILE__,'error'=>UPLOAD_ERR_OK,'size'=>100];self::assertWPError($this->panel()->process($this->post($operation,['image_job_id'=>$job['id'],'confirm'=>'1','source_sha256'=>str_repeat('a',64),'rights_note'=>'Synthetic rights','source_note'=>'Synthetic source'])));}self::assertSame('PREPARED',(new ImageGenerationExecution())->read('personalized_pod',$job['id'])['state']);}
 public function testAuthorizedArtifactPreviewIsUnapprovedAndDerivationUsesFileControls():void {$this->panel();$candidate=ImagePanelFixture::candidate($this->spec,$this->policy);self::assertSame('SUCCEEDED',$candidate['state']);$html=$this->html();self::assertStringContainsString('data:image/png;base64,',$html);self::assertStringContainsString('Unapproved raster candidate',$html);self::assertStringContainsString('not editable vector',$html);self::assertStringContainsString('name="derivative_svg"',$html);self::assertStringContainsString('name="source_sha256"',$html);self::assertStringNotContainsString('SYNTHETIC-NOT-A-CREDENTIAL',$html);}
 public function testTypedPolicyReviewPinsExistingRowsAndSavesDisabled():void {$p=$this->policy['policy'];$out=$this->panel()->process($this->post('review_policy',['policy_key'=>'panel-'.wp_generate_uuid4(),'policy_version'=>'v1','task_id'=>(string)$p['binding']['task_id'],'model_id'=>(string)array_key_first($p['binding']['provider_models']),'integration_id'=>(string)$p['integration_id'],'size'=>'1024x1024','quality'=>'low','maximum_task_charge'=>'0.020000','currency'=>'USD','timeout_seconds'=>'20','max_output_bytes'=>'2097152','prompt_version'=>'v1','terms_source_sha256'=>hash('sha256','Synthetic policy terms'),'confirm'=>'1','enabled'=>'1']));self::assertIsArray($out);self::assertFalse($out['image_policy']['policy']['enabled']);self::assertSame(['ORIGINAL_ARTWORK'],$out['image_policy']['policy']['engines']);}
 public function testDefaultServerShowsUnavailableCustodyAndCannotAcceptCustodyFromRequest():void {$job=$this->prepare();$html=$this->html();self::assertStringContainsString('NETWORK_CUSTODY_UNAVAILABLE',$html);$doc=new DOMDocument();$doc->loadHTML($html,LIBXML_NOERROR);$x=new DOMXPath($doc);self::assertSame(1,$x->query('//form[input[@name="operation" and @value="design_image_run"]]//button[@disabled]')->length);self::assertWPError($this->panel()->process($this->post('run',['image_job_id'=>$job['id'],'confirm'=>'1','custody'=>'client-selected'])));self::assertSame('PREPARED',(new ImageGenerationExecution())->read('personalized_pod',$job['id'])['state']);}
 public function testResearchActorWithoutAiGetsHeldAuthorizationExplanation():void {wp_get_current_user()->add_cap('manage_digiforge_ai',false);$html=$this->html();self::assertStringContainsString('AI authorization is required',$html);self::assertStringNotContainsString('value="design_image_prepare"',$html);}
 public function testRecoveryRecordsUnknownAndCannotRetryAutomatically():void {$job=$this->prepare();$j=new ImageGenerationJournal();$v=$j->append($job['id'],$job['event_sha256'],['state'=>'RESERVED','usage_id'=>123]);self::assertIsArray($v);$v=$this->panel()->process($this->post('recover',['image_job_id'=>$job['id'],'confirm'=>'1']));self::assertIsArray($v);self::assertSame('UNKNOWN',$v['image_job']['state']);self::assertWPError($this->panel()->process($this->post('run',['image_job_id'=>$job['id'],'confirm'=>'1'])));}
 public function testForeignCreatorsValidAttemptDoesNotBlockNormalOperatorControls():void {
  $actor=get_current_user_id();$mine=$this->prepare();$other=self::factory()->user->create(['role'=>'administrator']);wp_set_current_user($other);ShopAccessFixture::authorizeActor($other,['personalized_pod'],['manage_digiforge_ai','manage_digiforge_pod','manage_digiforge_research']);global $wpdb;$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');$foreign=$this->prepare();wp_set_current_user($actor);$html=$this->html();self::assertStringContainsString($mine['id'],$html);self::assertStringNotContainsString($foreign['id'],$html);self::assertStringContainsString('value="design_image_prepare"',$html);self::assertStringNotContainsString('Image policy or job evidence is unavailable',$html);self::assertWPError($this->panel()->process($this->post('inspect',['image_job_id'=>$foreign['id']])));self::assertTrue(DigiForge\Core\Settings::safety_locked());
 }

}
